/**
 * cmux-session.test.ts — shape/registration smoke for extensions/cmux-session.ts
 * Run: npx tsx extensions/cmux-session.test.ts
 * Wired: ci.yml's `verify` job (per-PR) and ci-main.yml (post-merge) — a pin that
 * runs nowhere enforces nothing, which is exactly how #1138's v2 snapshot sat in
 * `main` while the farm ran v4.
 *
 * The file is cmux-managed (regenerated by `cmux hooks pi install`); the repo
 * copy is a version-controlled snapshot for bootstrap. These tests pin the
 * minimal contract so a corrupted/regressed sync is caught: default factory
 * exists and registers the lifecycle handlers pi relies on, and the snapshot is
 * the exact payload we believe it is — its marker version AND its bytes.
 *
 * HONEST SCOPE — what this does NOT see. The literal below is recorded in the
 * same commit as the file, so the suite compares the repo copy against its own
 * pin; it can never observe the FARM. CI runs off-machine and never reads
 * `~/.pi/agent/extensions/`, so cmux advancing the live file to v5 leaves this
 * repo holding v4 with a GREEN suite. What it catches is the committed snapshot
 * being REPLACED by a different payload without the pin moving (the v2-in-main
 * shape from #1138) — not farm staleness. That residual is named on #1138 and is
 * deliberately not closed here.
 */
import { ok, equal } from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import cmuxPiSessionExtension from "./cmux-session.js";

/**
 * The snapshot's marker version. cmux upgrades the live file
 * (`~/.pi/agent/extensions/cmux-session.ts`) in place; this repo copy is only a
 * bootstrap snapshot, so it can silently fall behind with nothing in `main`
 * saying so — the drift #1138 exists to catch. Pin the version here so an
 * unrecorded swap of the snapshot fails the suite instead of being discovered by
 * a fleet survey. When the farm advances, re-sync this file and update this
 * literal in the same commit. (Kept alongside EXPECTED_SHA256 deliberately: the
 * hash is the identity that bites, the marker is the readable version a failure
 * message can name — #1760 records the payload hash as the authority.)
 *
 * A marker alone is NOT a payload identity (#1760's decision, and the reason
 * v2→v4 went unnoticed): a partial copy, a local edit, or simply the wrong blob
 * kept line 1 intact and passed. EXPECTED_SHA256 is the payload half, adopted
 * from the repo's own stamp standard (scripts/check-version-stamp.mjs records
 * the payload hash, not a commit pointer). Both literals are updated together
 * on a re-sync.
 *
 * Non-vacuity (re-run to check the pins still bite): the same test file against
 * the previous snapshot fails THREE tests — the handler test (v2 registers no
 * `agent_start`) plus both pins — and exits 1 —
 *   S=$(mktemp -d); cp extensions/cmux-session.test.ts "$S/"
 *   git show 54049bea3e0918b1ae1b6ea6320eb37ab7c9fa14:extensions/cmux-session.ts > "$S/cmux-session.ts"
 *   npx tsx "$S/cmux-session.test.ts"   # → 1 passed, 3 failed, exit 1
 *                                       # ❌ marker: line 1 is v2, expected v4
 *                                       # ❌ payload: sha256 differs
 * A second, sharper mutation — a v4 payload with a line-1-preserving edit —
 * fails the PAYLOAD test ALONE (3 passed, 1 failed, exit 1), which is the class
 * a marker literal cannot see.
 */
const EXPECTED_MARKER = "// cmux-pi-session-extension-marker v4";
const EXPECTED_SHA256 = "35764c495e4e576e44cce80c0a3e4b67c25ac6e0c42729455d40acf30ca2b9fc";

let passed = 0, failed = 0;
function test(name: string, fn: () => void) {
  try {
    fn();
    passed++;
    console.log(`  ✅ ${name}`);
  } catch (err: any) {
    failed++;
    console.log(`  ❌ ${name}: ${err.message}`);
  }
}

test("default export is a factory function", () => {
  equal(typeof cmuxPiSessionExtension, "function");
});

test("factory registers the lifecycle handlers pi relies on", () => {
  const handlers: Record<string, unknown> = {};
  const pi: any = { on: (ev: string, h: unknown) => { handlers[ev] = h; } };
  cmuxPiSessionExtension(pi);
  for (const ev of [
    "session_start",
    "before_agent_start",
    "agent_start",
    "tool_execution_start",
    "tool_execution_end",
    "agent_end",
    "agent_settled",
    "session_shutdown",
  ]) {
    ok(handlers[ev], `handler registered for ${ev}`);
  }
});

test("snapshot marker line pins the v4 farm version", () => {
  const source = readFileSync(new URL("./cmux-session.ts", import.meta.url), "utf8");
  const markerLine = source.split("\n", 1)[0];
  equal(
    markerLine,
    EXPECTED_MARKER,
    `extensions/cmux-session.ts is not the expected snapshot — line 1 is ` +
      `${JSON.stringify(markerLine)}. cmux upgrades the live file in place; ` +
      `re-sync this snapshot from the farm and update EXPECTED_MARKER (#1138).`,
  );
});

test("snapshot payload hash pins the exact bytes, not just the version line", () => {
  // Bytes, not a decoded string: the pin must describe the file the commit
  // records. `readFileSync` without an encoding returns the raw Buffer.
  const bytes = readFileSync(new URL("./cmux-session.ts", import.meta.url));
  const actual = createHash("sha256").update(bytes).digest("hex");
  equal(
    actual,
    EXPECTED_SHA256,
    `extensions/cmux-session.ts is not the payload EXPECTED_SHA256 records ` +
      `(sha256 ${actual}). A marker-identical but different payload is exactly ` +
      `the drift class #1760 exists for; re-sync from the farm and update BOTH ` +
      `EXPECTED_MARKER and EXPECTED_SHA256 or EXPECTED_SHA256 alone (#1138).`,
  );
});

console.log(`\n${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
